static.userAgent:
@layer {
html {
    color-scheme: dark !important;
}
iframe {
    color-scheme: dark !important;
}
html, body {
    border-color: var(--darkreader-border-4c4c4c, #56567b);
    color: var(--darkreader-text-000000, #e8e8ef);
}
a {
    color: var(--darkreader-text-0040ff, #3391ff);
}
table {
    border-color: var(--darkreader-border-808080, #404073);
}
mark {
    color: var(--darkreader-text-000000, #e8e8ef);
}
::placeholder {
    color: var(--darkreader-text-a9a9a9, #9c9cba);
}
input:-webkit-autofill,
textarea:-webkit-autofill,
select:-webkit-autofill {
    background-color: var(--darkreader-background-faffbd, #343700) !important;
    color: var(--darkreader-text-000000, #e8e8ef) !important;
}
::selection {
    background-color: var(--darkreader-background-0060d4, #004daa) !important;
    color: var(--darkreader-text-ffffff, #e8e8ef) !important;
}
::-moz-selection {
    background-color: var(--darkreader-background-0060d4, #004daa) !important;
    color: var(--darkreader-text-ffffff, #e8e8ef) !important;
}
}

